#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Ki Ki Shop – SINGLE FILE (Bot + HTML Web)
Run:    python kiki_shop_all.py
Render: python kiki_shop_all.py
"""
from __future__ import annotations

import base64
import json
import logging
import os
import sys
import tempfile
import threading
import time

logging.basicConfig(
    format="%(asctime)s | %(levelname)s | %(name)s | %(message)s",
    level=logging.INFO,
)
log = logging.getLogger("kiki-all")

_BOT_B64 = ""
_WEB_B64 = ""
_ASSETS = json.loads('{"templates/login.html": "", "templates/shop.html": "", "static/style.css": "", "static/app.js": ""}')


def _w(path: str, data: bytes):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "wb") as f:
        f.write(data)


def setup_workdir() -> str:
    work = tempfile.mkdtemp(prefix="kiki_")
    _w(os.path.join(work, "bot.py"), base64.b64decode(_BOT_B64))
    _w(os.path.join(work, "web_app.py"), base64.b64decode(_WEB_B64))
    for rel, b64s in _ASSETS.items():
        _w(os.path.join(work, rel), base64.b64decode(b64s))
    log.info("Extracted to %s", work)
    return work


def run_bot(work: str):
    time.sleep(2)
    try:
        if work not in sys.path:
            sys.path.insert(0, work)
        prev = os.getcwd()
        os.chdir(work)
        import importlib
        bot = importlib.import_module("bot")
        log.info("Bot start | token=%s", bool(getattr(bot, "BOT_TOKEN", "")))
        bot.main()
    except Exception:
        log.exception("Bot failed")
    finally:
        try:
            os.chdir(prev)
        except Exception:
            pass


def main():
    work = setup_workdir()
    if work not in sys.path:
        sys.path.insert(0, work)
    os.chdir(work)

    threading.Thread(target=run_bot, args=(work,), name="bot", daemon=True).start()

    import importlib
    web_app = importlib.import_module("web_app")
    # Flask needs correct template folder
    web_app.app.template_folder = os.path.join(work, "templates")
    web_app.app.static_folder = os.path.join(work, "static")
    log.info("Web %s:%s", web_app.HOST, web_app.PORT)
    web_app.init_web_db()
    web_app.app.run(
        host=web_app.HOST,
        port=web_app.PORT,
        debug=False,
        threaded=True,
        use_reloader=False,
    )


if __name__ == "__main__":
    main()
